    RCC->PLLCFGR = (RCC_PLLCFGR_PLLSRC_0 | RCC_PLLCFGR_PLLSRC_1)
                 | ((2UL << RCC_PLLCFGR_PLLM_Pos) & RCC_PLLCFGR_PLLM)
