    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN;

    GPIOB->MODER   &= ~((3UL << (8 * 2)) | (3UL << (9 * 2)));
    GPIOB->MODER   |=  ((2UL << (8 * 2)) | (2UL << (9 * 2)));
